internal object DuaAmDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("ከጉዳት ሁሉ ጥበቃ", "በአላህ ስም በምድርም በሰማያትም ውስጥ በስሙ ምንም የማይጎዳው፤ እርሱም ሰሚው ዐዋቂው ነው።", "ጠዋት እና ማታ ሶስት ጊዜ.", "ጠዋትና ማታ ሶስት ጊዜ የሚናገረው ምንም አይጎዳውም።"),
        "dua_raditu_billahi" to DuaText("አላህን እንደ ጌታ መርካት።", "በአላህ ጌታዬ፣ እስልምና እንደ ሀይማኖቴ እና በሙሀመድ ﷺ ነብይ በመሆን ደስተኛ ነኝ።", "ሶስት ጊዜ ጥዋት እና ማታ.", "በቂያማ ቀን እሱን ማስደሰት በአላህ ላይ መብት ይሆናል።"),
        "dua_hasbiyallah" to DuaText("ሀስቢያላህ (አላህ በቂ ነው)", "አላህ በቂዬ ነው። ከእርሱ በቀር ሌላ አምላክ የለም። በእርሱ ተጠጋሁ እርሱም የዐርሽ ጌታ ነው።", "ሰባት ጊዜ ጥዋት እና ማታ.", "የቁርኣን አንቀጽ; በዱንያም በመጨረሻውም ዓለም ጭንቀት ላይ አላህ በቃ።"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("ሱብሀንአላህ ወ ቢሀምዲሂ", "ክብር ምስጋና ለአላህ ይገባው።", "በቀን አንድ መቶ ጊዜ.", "በቀን መቶ ጊዜ የሚናገር ሁሉ ኃጢአቱ ይሰረይለታል፣ እንደ ባሕር አረፋ ቢሆንም።"),
        "dua_tahleel_100" to DuaText("ላ ኢላሀ ኢለላሁ ወህደሁ", "ሊመለክ የሚገባው አላህ ብቻ ነው፣ እርሱ ብቻውን ነው፣ አጋር የለውም። ንግሥናው የርሱ ብቻ ነው፤ ምስጋናም የርሱ ብቻ ነው። እርሱም በነገሩ ሁሉ ላይ ቻይ ነው።", "በቀን አንድ መቶ ጊዜ በመናገር ታላቅ በጎነት።", "አስር ባሪያዎችን ነፃ የማውጣት፣መቶ መልካም ስራ የተፃፈ፣መቶ ኃጢያት የተሰረዘበት እና ከሸይጣን የመጠበቅ ሽልማት እስከ ምሽት።"),
        "dua_leaving_mosque" to DuaText("ከመስጂድ መውጣት", "አላህ ሆይ ከችሮታህ እጠይቅሃለሁ።", "በግራ እግሩ ከመስጂድ ሲወጡ።", "ከመስጂድ ሲወጡ የአላህን ችሮታና ሲሳይ መጠየቅ።"),
        "dua_after_adhan" to DuaText("ከአድሃን በኋላ", "አላህ ሆይ የዚህ ፍፁም ጥሪ እና ሊፀና ያለው ፀሎት ጌታ ሆይ ለሙሀመድ ﷺ አል-ወሲላህ እና መልካም ምግባርን ስጥ እና ቃል ወደገባህለት የተመሰገነ ቦታ ከፍ አድርግለት።", "አድሃኑ ከተጠናቀቀ በኋላ።", "ይህንን የሚናገር የቂያማ ቀን የነብዩ ﷺ አማላጅነት ይሰጠዋል ።"),
        "dua_after_salah_istighfar" to DuaText("ከፋርድ ሳላህ በኋላ", "የአላህን ምህረት እጠይቃለሁ (3 ጊዜ)። አሏህ ሆይ አንተ አሰላም ነህ ከአንተም ሰላም ነው። የግርማና የክብር ባለቤት ሆይ ተባረክ።", "ወዲያው ከሰላም በኋላ።", "ነብዩ ﷺ ይህንን ከእያንዳንዱ የግዴታ ጸሎት በኋላ አንብበውታል።"),
        "dua_after_salah_help_dhikr" to DuaText("እንዳስታውስህ እርዳኝ።", "አላህ ሆይ አንተን እንዳስታውስ፣ አንተን እንዳመሰግንህና አንተን በመልካም መንገድ እንድገዛህ እርዳኝ።", "ከእያንዳንዱ ጸሎት በኋላ - ነቢዩ ﷺ ሙአዝ (RA) እንዲናገር መክሯቸዋል።", "የነቢዩ ልዩ ምክር ﷺ - በአምልኮ ውስጥ የላቀ እና የማያቋርጥ."),
        "dua_sleep_tasbeeh" to DuaText("Tasbeeh-e-Fatimi ከመተኛቱ በፊት", "ክብር ለአላህ ይገባው(33)፣ምስጋና ሁሉ ለአላህ ይሁን (33)፣ አላህ ታላቁ ነው (34)።", "ከመተኛቱ በፊት - ነቢዩ ﷺ ለፋጢማ እና አሊ (RA) አስተማሩት።", "ነብዩ ﷺ ከአገልጋይ ይሻለኛል ብለዋል።"),
        "dua_sleep_qina_adhab" to DuaText("ከቅጣት መከላከል", "አላህ ሆይ ባሮችህን በምትቀሰቅስበት ቀን ከቅጣትህ ጠብቀኝ።", "ሶስት ጊዜ, ቀኝ እጅ በጉንጩ ስር ተቀምጧል.", "እንቅልፍን ወደ ሞት ማስታወሻ እና ለመጨረሻው ዓለም መዘጋጀትን ይለውጣል።"),
        "dua_bad_dream" to DuaText("ከመጥፎ ህልም በኋላ", "ከተረገመው ሸይጣን በአላህ እጠበቃለሁ።", "ከመጥፎ ህልም በኋላ: ደረቅ-በግራ በኩል በትንሹ ወደ ግራ ሶስት ጊዜ ይትፉ, ከዚያም ወደ ሌላኛው ጎን ያዙሩ.", "መጥፎው ሕልም አይጎዳህም; ስለሱ ለማንም አትንገር።"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("ያ ሀዩ ያ ቃዩም", "አንተ ሁል ጊዜ የምትኖር የሁሉ ጠባቂ ሆይ! በምህረትህ እርዳታ እሻለሁ።", "አንድ ጉዳይ በጣም ከባድ በሚሆንበት ጊዜ.", "ﷺ ነቢዩን አንድ ነገር ባስጨነቀ ጊዜ እንዲህ ይሉ ነበር።"),
        "dua_entering_market" to DuaText("ወደ ገበያ ቦታ መግባት", "ሊመለክ የሚገባው አላህ ብቻ ነው፣ እርሱ ብቻውን ነው፣ አጋር የለውም። ንግሥናው የርሱ ብቻ ነው፤ ምስጋናም የርሱ ብቻ ነው። ሕያው ያደርጋል ይገድላልም እርሱም ሕያው ነው አይሞትምም። መልካም ነገር ሁሉ በእጁ ነው። እርሱም በነገሩ ሁሉ ላይ ቻይ ነው።", "ወደ ገበያው ቦታ ሲገቡ.", "ሐዲሱ ለእርሱ ታላቅ ምንዳ ይጠቅሳል (አንድ ሚሊዮን መልካም ሥራዎች)።"),
        "dua_adam_forgiveness" to DuaText("የነቢዩ አደም ዱዓ (AS)", "ጌታችን ሆይ! ራሳችንን በድለናል ለኛ ይቅር ባትሉልንም ለኛም ምሕረትን ካላደረግክ። እኛ ከከሳሪዎቹ እንኾናለን።", "የአዳም እና የሐዋው የንስሐ ዱዓ (AS)።", "የሰው ልጅ የመጀመሪያ ንስሃ - አላህ ተቀበለው።"),
        "dua_abu_bakr" to DuaText("ዱዓ አስተማረው አቡበክር (RA)", "አላህ ሆይ ራሴን በጣም በደልኩ ከአንተ በቀር ኃጢአትን የሚምር የለምና ከራስህ ዘንድ ምህረትን ስጠኝና ማረኝ። አንተ መሓሪ አዛኝ ነህና።", "ነብዩ ﷺ ለአቡበከር አስ-ሲዲቅ (RA) በጸሎት እንዲናገር አስተምረውታል (ከተሻሁድ በኋላ)።", "ለሶላት መጨረሻ የሱና ዱዓ።"),
        "dua_astaghfirullah_atubu" to DuaText("ዕለታዊ ኢስቲግፋር", "የአላህን ምህረት እጠይቃለሁ ወደርሱም ጸጸትን እመለሳለሁ።", "ነቢዩ ﷺ በቀን ከሰባ ጊዜ በላይ ይቅርታ ጠየቁ።", "ነብዩ ﷺ እንዲህ ብለዋል፡- የአላህን ምህረት እጠይቃለሁ እናም በቀን ከሰባ ጊዜ በላይ ተፀፅቻለሁ።"),
        "dua_laylatul_qadr" to DuaText("ለለይለተል ቀድር ዱዓ", "አላህ ሆይ አንተ በጣም መሓሪ ነህ ይቅር ማለትን ትወዳለህና ይቅር በለኝ", "ለለይለተል ቀድር (RA) ለአይሻ ተማረ።", "የረመዷን የመጨረሻ ሌሊቶች እና የለይለተልቃድር ሌሊቶች ልዩ ዱዓ።"),
        "dua_family_coolness" to DuaText("የዓይን ቅዝቃዜ (የትዳር ጓደኛ እና ልጆች)", "ጌታችን ሆይ ከትዳር አጋሮቻችንና ከዘሮቻችን የአይናችንን ቅዝቃዜ ስጠን የጻድቃን መሪዎች አድርገን።", "የቁርዓን ዱዓ ለጻድቅ የትዳር አጋር እና ልጆች።", "ሰላም ለቤት እና ለጻድቅ ልጆች።"),
        "dua_righteous_children" to DuaText("ለጻድቅ ዘር", "ጌታዬ ሆይ ከራስህ ንፁህ ዘርን ስጠኝ። አንተ ልመናን ሰሚ ነህና።", "የነቢዩ ዘካርያስ ዱአ (AS)።", "ልጆች ለሚፈልጉ የቁርዓን ዱአ።"),
        "dua_ibrahim_prayer_family" to DuaText("የጸሎት አራማጆች", "ጌታዬ ሆይ ጸሎትን አስተባባሪ አድርገኝ ከዘሮቼም ጌታችን ሆይ ልመናዬን ተቀበል። ጌታችን ሆይ ለኔ፣ ለወላጆቼም፣ ለምእመናንም ምሕረትን አድርግ።", "የነቢዩ ኢብራሂም ዱዓ (AS) ለራሱ እና ለዘሮቻቸው።", "በጸሎቱ መጨረሻ ላይ በብዛት ይነበባል።"),
        "dua_newlywed" to DuaText("አዲስ ተጋቢዎችን እንኳን ደስ አለዎት", "አሏህ ይባርካችሁ፣ በረካችሁን አውርዱ፣ ሁለታችሁንም በመልካም ያገናኛችሁ።", "አንድ ሰው በትዳራቸው ላይ እንኳን ደስ አለዎት.", "የሱና እንኳን ደስ አላችሁ ለትዳር።"),
        "dua_before_eating" to DuaText("ከመብላትዎ በፊት", "በአላህ ስም። (ከተረሳ፡) በአላህ ስም መጀመሪያውና መጨረሻው ላይ።", "ከመብላቱ በፊት. ከረሳህ በከፊል ተናገር።", "ቢስሚላህ ማለት ሸይጣን ምግቡን እንዳይጋራ ያደርገዋል።"),
        "dua_after_eating" to DuaText("ከምግብ በኋላ", "ይህን ላበላኝና በለገሠኝ በኩል ያለ ምንም ጉልበትና ጉልበት ለሰጠኝ አላህ ምስጋና ይገባው።", "ምግቡን ከጨረሱ በኋላ.", "ይቅር ተብሏል ያለው ያለፈው ኃጢአት።"),
        "dua_host" to DuaText("ለአስተናጋጁ", "አሏህ ሆይ በሰጠሃቸው ነገር ባርካቸው፣ ይቅር በላቸውና እዘንላቸው።", "ለአስተናጋጁ፣ በአንድ ሰው ቤት ከበላ በኋላ።", "አስተናጋጁን በሱና መንገድ ማመስገን።"),
        "dua_breaking_fast" to DuaText("ጾምን ሲያፈርሱ", "ጥሙ አልፏል፣ ደም መላሽ ቧንቧዎች ረጥበዋል፣ ምንዳውም የተረጋገጠው አላህ ከፈቀደ ነው።", "በኢፍጣር ጊዜ።", "ነብዩ ﷺ ፆማቸውን ሲፈቱ እንዲህ ብለዋል::"),
        "dua_new_clothes" to DuaText("አዲስ ልብስ መልበስ", "አላህ ሆይ ምስጋና ሁሉ የአንተ ነው; ይህን አለበስከኝ. ከመልካምነቱና ከተሰራበት ነገር መልካሙን እጠይቅሃለሁ፤ ከተሰራበትም መጥፎነት ከመጥፎነቱም በአንተ እጠበቃለሁ።", "አዲስ ልብስ ሲለብሱ (እንደ ሸሚዝ ወይም ጥምጥም በመሰየም)።", "ነብዩ ﷺ አዲስ ልብስ ለብሰው ይህን ዱዓ አድርገዋል። (የእለት ተእለት የአለባበስ ዱዓ 'በአለባበስ' ስር ነው።)"),
        "dua_rabbana_atina" to DuaText("በዱንያም በመጨረሻውም መልካም", "ጌታችን ሆይ በዱንያ መልካምን በመጨረሻይቱም ዓለም መልካም ነገርን ስጠን ከእሳትም ቅጣት ጠብቀን።", "ነብዩ ﷺ ብዙ ጊዜ ያደረጉት ዱዓ።", "የዱንያም ሆነ የኋለኛይቱን መልካም ነገር ሁሉ የሚሰበስብ ዱዓ።"),
        "dua_rabbi_zidni_ilma" to DuaText("በእውቀት መጨመር", "ጌታዬ እውቀትን ጨምርልኝ።", "ለእውቀት መጨመር.", "አላህ ነብዩ ﷺ እውቀትን እንጂ ሌላን እንዲጨምሩ አዘዛቸው።"),
        "dua_musa_sharh_sadr" to DuaText("የደረት መክፈቻ (ሙሳ AS)", "ጌታዬ ሆይ ደረቴን አስፋልልኝ፣ ስራዬንም አቅልልኝ፣ ንግግሬንም እንዲረዱ ቋጠሮዬን ከአንደበቴ ፍታ።", "ከፈተና በፊት, ንግግር ወይም ማንኛውም አስቸጋሪ ተግባር.", "የነቢዩ ሙሳ ዱዓ (AS) - የልብ መረጋጋት እና በአንድ ሰው ሥራ ውስጥ ምቾት።"),
        "dua_la_tuzigh" to DuaText("የልብ ጽናት", "ጌታችን ሆይ አንተ ከመራኸን በኋላ ልቦቻችንን አትዘንግ ከራስህም የሆነን እዝነት ስጠን። አንተ በእርግጥ ሰጪ ነህ።", "በመመሪያው ላይ ለመጽናት።", "በእምነት ጸንቶ ለመኖር ዱዓ።"),
        "dua_ya_muqallib" to DuaText("የልቦች ተርነር ሆይ", "የልቦች ባለቤት ሆይ፣ ልቤን በሃይማኖትህ ላይ አፅና።", "ነቢዩ ﷺ ብዙ ጊዜ ይህንን ዱዓ አድርገዋል።", "ኡሙ ሰላማህ (RA) እንዳለው ነብዩ ﷺ ብዙ ጊዜ ያደረጉት ዱዓ።"),
        "dua_la_tuakhidhna" to DuaText("የሱረቱ አል-በቀራህ የመጨረሻ ጥቅሶች", "ጌታችን ሆይ ከረሳን ወይም ከተሳሳትን ወደ ሥራ አትውሰደን። ጌታችን ሆይ ከኛ በፊት በነበሩት ላይ እንደጫንክ ሸክም በኛ ላይ አታድርግ። ጌታችን ሆይ የማንችለውን አትጫንብን። ይቅር በለን, ይቅር በለን እና ማረን. አንተ ረዳታችን ነህና በከሓዲዎቹ ሕዝቦች ላይ እርዳን።", "ማታ ከመተኛቱ በፊት - የሱራ አል-በቀራ የመጨረሻዎቹ ሁለት ጥቅሶች.", "በሌሊት የሱረቱል በቀራህ የመጨረሻዎቹን ሁለት አንቀጾች ያነበበ እነሱ በቂ ናቸው።"),
        "dua_visiting_sick" to DuaText("የታመሙትን መጎብኘት", "የታላቁን ዐርሽ ጌታ አላህ እንዲፈውስህ እጠይቃለሁ።", "የታመሙትን ሲጎበኙ ሰባት ጊዜ.", "የሞት ጊዜ ካልደረሰ አላህ ፈውሶታል።"),
        "dua_ruqyah_pain" to DuaText("ለአካል ህመም", "ከሚሰማኝ እና ከምፈራው ክፉ ነገር በአላህ እና በኃይሉ እጠበቃለሁ።", "እጅህን በተጎዳበት ቦታ አስቀምጠው, ቢስሚላህ ሶስት ጊዜ ተናገር, ከዚያም ይህን ዱዓ ሰባት ጊዜ.", "ነቢዩ ﷺ ለኡስማን ኢብኑ አቢል-አስ (RA) ለህመም አስተምረውታል።"),
        "dua_ruqyah_nabawi" to DuaText("ለታመሙ ትንቢታዊ ሩቅያህ", "የሰው ልጅ ጌታ አላህ ሆይ! ጉዳቱን አስወግደህ ፈውሰኝ አንተ ፈውስ ነህና; ከመድኃኒትህ በቀር ምንም ዓይነት በሽታን የማይተው መድኃኒት የለም።", "በታመመው ሰው ላይ እጁን ሲያስተላልፉ.", "ነቢዩ ﷺ የታመሙ የቤተሰባቸውን አባላት ሲጎበኙ ይህንን አንብበው ነበር።"),
        "dua_kalimat_tammat" to DuaText("ፍጹም በሆነ ቃል መጠጊያ መፈለግ", "ፍፁም በሆነው የአላህ ቃል እጠበቃለሁ ከፈጠረው መጥፎ ነገር።", "በአንድ ቦታ ላይ ሲቆሙ, ወይም ምሽት ላይ.", "አንድ ቦታ ላይ ቆሞ ይህን የሚናገር ሰው እስካልተወ ድረስ ምንም አይጎዳውም።"),
        "dua_evil_eye" to DuaText("ለልጆች ጥበቃ (ክፉ ዓይን)", "ፍጹም በሆነው የአላህ ቃል ከእያንዳንዱ ሰይጣን እና መርዛማ ፍጡር እንዲሁም ከማንኛውም ጎጂ ዓይን ጥበቃን እሻለሁ።", "ነቢዩ ﷺ ይህንን ሀሰን እና ሁሴን (RA) ላይ አንብበውታል።", "ልጆችን ከመጥፎ ዓይን እና ጉዳት ለመጠበቅ የሱና ዱዓ (ለአንድ ልጅ 'ኡኢዱካ' ይበሉ)።"),
        "dua_seeing_afflicted" to DuaText("በሙከራ ላይ ያለን ሰው ማየት", "ምስጋና ሁሉ ለአላህ ይሁን ለፈተነህ ለላቀኝ፣ ከፍጡራኑም ላበለጠኝ።", "በሙከራ ላይ ያለ ሰው ሲመለከት (ለራስህ በጸጥታ ተናገር)።", "ከዚያ ፍርድ የተጠበቀ ነው የሚል።"),
        "dua_istikhara" to DuaText("ሰላት አል-ኢስቲካራ", "አላህ ሆይ በእውቀትህ መልካሙን እሻለሁ፣በአንተ ሃይል ችሎታን እሻለሁ፣ከታላቅ ችሮታህም እጠይቅሃለሁ። አንተ ኃይል አለህ እኔም ምንም የለኝም; አንተ ታውቃለህ እኔም አላውቅም፤ አንተም ሩቁን ነገር ዐዋቂ ነህ። O Allah, if in Your knowledge this matter (bring it to mind) is good for my religion, my life and my end, then decree it for me, make it easy for me and bless me in it. And if in Your knowledge this matter is bad for my religion, my life and my end, then turn it away from me and turn me away from it, and decree for me the good wherever it may be, then make me content with it.", "ከሁለት ረከዓ የውዴታ ሶላት በኋላ በሚፈቀደው ጉዳይ ላይ የተሻለውን ለመፈለግ።", "ነብዩ ﷺ የቁርኣን ሱራ እንዳስተማሯቸው ለሶሓቦች ኢስቲካራ በሁሉም ጉዳዮች አስተምረዋል።"),
    )
}
